UPDATE refresh_tokens
   SET revoked_at     = #{revokedAt},
       revoke_reason  = #{revokeReason},
       replaced_by_id = #{replacedById}
 WHERE id = #{id}

UPDATE refresh_tokens
   SET revoked_at    = #{now},
       revoke_reason = #{reason}
 WHERE user_id = #{userId}
   AND revoked_at IS NULL
